from __future__ import annotations

import importlib
import importlib.util
import inspect
import sys
import threading
from abc import ABC, abstractmethod
from collections.abc import Callable
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from types import ModuleType
from typing import TypeVar

from freesolo.datasets import TaskExample, target_messages

from ..contracts.markdown import build_oracle_messages
from ..contracts.types import ChatMessage, ContractSpec
from .types import (
    EnvironmentEpisode,
    EnvironmentStepResult,
    RewardResult,
)

_DEFAULT_ENVIRONMENT_FACTORY = "load_environment"
_REPO_ENVIRONMENT_FILE = Path("freesolo") / "environment.py"
_REPO_ENVIRONMENT_REFERENCE = "freesolo/environment.py:load_environment"

_ScoreItem = TypeVar("_ScoreItem")


def _with_system_prompt(
    messages: list[ChatMessage],
    prompt_text: str,
) -> list[ChatMessage]:
    system_text = prompt_text.strip()
    out = list(messages)
    if not system_text:
        return out
    if any(
        str(message.get("role") or "").strip().lower() == "system" for message in out
    ):
        return out
    return [{"role": "system", "content": system_text}, *out]


class Environment(ABC):
    """Task behavior adapter used by generated environments and oracle flows.

    Single-turn and multi-turn execution are peer branches: the default episode
    hooks implement the direct prompt/response branch, and interactive
    environments override the same hooks to keep a bounded transcript.
    """

    # Cap on concurrent score_response/score_episode calls, enforced globally
    # across overlapping score_responses/score_episodes calls (GRPO scores
    # whole batches concurrently). Set to 1 when the scorer owns thread-affine
    # state (sqlite handles, browser sessions); serial environments are also
    # scored on the event-loop thread by GRPO.
    max_score_concurrency: int = 8

    _score_pool: ThreadPoolExecutor | None = None
    _score_pool_lock = threading.Lock()

    @abstractmethod
    def build_prompt_messages(
        self,
        example: TaskExample,
        prompt_text: str,
    ) -> list[ChatMessage]:
        """Build the model-input messages for one environment example."""

    def start_episode(
        self,
        example: TaskExample,
        prompt_text: str,
    ) -> list[ChatMessage]:
        """Return the initial model messages for an environment episode."""

        return _with_system_prompt(
            self.build_prompt_messages(example, prompt_text),
            prompt_text,
        )

    def max_episode_turns(self, example: TaskExample) -> int:
        """Maximum assistant actions to sample before forcing the episode terminal."""

        _ = example
        return 1

    def step_episode(
        self,
        example: TaskExample,
        messages: list[ChatMessage],
        assistant_response: str,
    ) -> EnvironmentStepResult:
        """Advance the environment after one assistant action.

        ``messages`` includes the assistant action being stepped. Multi-turn
        environments can append user/tool/environment messages and keep the
        episode open by returning ``done=False``.
        """

        return EnvironmentStepResult(
            done=True,
            final_response_text=self.normalize_response_text(
                example, assistant_response
            ),
        )

    def build_oracle_messages(
        self,
        example: TaskExample,
        contract_text: str,
        *,
        contract_spec: ContractSpec | None = None,
    ) -> list[ChatMessage]:
        return build_oracle_messages(
            example.input,
            contract_text,
            contract_spec=contract_spec,
        )

    def extract_response_text(self, parsed_message: object) -> str:
        if isinstance(parsed_message, dict):
            content = parsed_message.get("content", "")
        else:
            content = getattr(parsed_message, "content", parsed_message)
        if isinstance(content, list):
            return "".join(
                str(part.get("text", ""))
                for part in content
                if isinstance(part, dict) and part.get("type") == "text"
            )
        return str(content)

    def normalize_response_text(
        self,
        example: TaskExample,
        response_text: str,
    ) -> str:
        return response_text

    def sft_completion(self, example: TaskExample) -> list[ChatMessage]:
        """Gold COMPLETION messages to append after the prompt for ONE SFT example.

        The single source of truth for "what the model should learn to produce" on this row.
        Delegates to :func:`freesolo.datasets.target_messages`, which turns the record's gold
        ``output`` into messages: a MULTI-TURN gold trajectory — assistant turns + tool calls +
        tool results + replies, authored as ``output = {"messages": [...]}`` or a bare message
        list — when the record carries one, otherwise a single assistant turn from a scalar
        ``output``. A trainer builds the SFT example as ``start_episode(example, ...) +
        sft_completion(example)`` and trains on the chat-templated text, so tool-using multi-turn
        trajectories are learned end-to-end with no trainer-side branching (``len(...) > 1`` is
        multi-turn). Override to synthesize or transform the gold completion.
        """
        return target_messages(example.output)

    @abstractmethod
    def score_response(
        self,
        example: TaskExample,
        response_text: str,
    ) -> RewardResult:
        """Return the scalar reward for one sampled response."""

    def _score_concurrently(
        self,
        score_one: Callable[[_ScoreItem], RewardResult],
        items: list[_ScoreItem],
    ) -> list[RewardResult]:
        if int(self.max_score_concurrency) <= 1:
            return [score_one(item) for item in items]
        # One pool per environment instance, sized once: overlapping calls
        # (GRPO scores whole batches concurrently) share its workers, so the
        # cap holds globally instead of multiplying per call.
        pool = self._score_pool
        if pool is None:
            with self._score_pool_lock:
                pool = self._score_pool
                if pool is None:
                    pool = ThreadPoolExecutor(
                        max_workers=int(self.max_score_concurrency)
                    )
                    self._score_pool = pool
        return list(pool.map(score_one, items))

    def score_responses(
        self,
        example: TaskExample,
        response_texts: list[str],
    ) -> list[RewardResult]:
        def score_one(response_text: str) -> RewardResult:
            return self.score_response(
                example,
                self.normalize_response_text(example, response_text),
            )

        return self._score_concurrently(score_one, response_texts)

    def score_episode(
        self,
        example: TaskExample,
        episode: EnvironmentEpisode,
    ) -> RewardResult:
        return self.score_response(example, episode.response_text)

    def score_episodes(
        self,
        example: TaskExample,
        episodes: list[EnvironmentEpisode],
    ) -> list[RewardResult]:
        if type(self).score_episode is not Environment.score_episode:

            def score_one(episode: EnvironmentEpisode) -> RewardResult:
                return self.score_episode(example, episode)

            return self._score_concurrently(score_one, episodes)
        return self.score_responses(
            example,
            [episode.response_text for episode in episodes],
        )


class EnvironmentSingleTurn(Environment):
    """Explicit authoring base for one prompt -> one assistant response tasks."""


class EnvironmentMultiTurn(Environment):
    """Explicit authoring base for bounded transcript-based tasks.

    Multi-turn environments use episode hooks as the primary interface and
    score the completed transcript through ``score_episode``.
    """

    @abstractmethod
    def start_episode(
        self,
        example: TaskExample,
        prompt_text: str,
    ) -> list[ChatMessage]:
        """Return the initial model messages for a multi-turn episode."""

    def build_prompt_messages(
        self,
        example: TaskExample,
        prompt_text: str,
    ) -> list[ChatMessage]:
        return self.start_episode(example, prompt_text)

    @abstractmethod
    def max_episode_turns(self, example: TaskExample) -> int:
        """Maximum assistant actions before forcing the episode terminal."""

    @abstractmethod
    def step_episode(
        self,
        example: TaskExample,
        messages: list[ChatMessage],
        assistant_response: str,
    ) -> EnvironmentStepResult:
        """Advance the environment after one assistant action."""

    @abstractmethod
    def score_episode(
        self,
        example: TaskExample,
        episode: EnvironmentEpisode,
    ) -> RewardResult:
        """Score the full episode transcript."""

    def score_response(
        self,
        example: TaskExample,
        response_text: str,
    ) -> RewardResult:
        return self.score_episode(
            example,
            EnvironmentEpisode(
                messages=(),
                response_text=self.normalize_response_text(example, response_text),
            ),
        )


def load_environment(
    reference: str | None = None,
    **kwargs: object,
) -> Environment:
    resolved_reference = _default_environment_reference(reference)
    factory = _resolve_factory(resolved_reference)
    environment = _call_factory(factory, kwargs)
    return _validate_environment(environment, reference=resolved_reference)


def _validate_environment(
    environment: object,
    *,
    reference: str | None = None,
) -> Environment:
    if not isinstance(environment, (EnvironmentSingleTurn, EnvironmentMultiTurn)):
        source = f" {reference!r}" if reference else ""
        raise TypeError(
            f"Environment loader{source} must return an instance of "
            "freesolo.environments.EnvironmentSingleTurn or "
            "freesolo.environments.EnvironmentMultiTurn. Canonical setup: define "
            "freesolo/environment.py with load_environment(...) returning a "
            "subclass of EnvironmentSingleTurn or EnvironmentMultiTurn."
        )
    return environment


def _default_environment_reference(
    reference: str | None = None,
    *,
    cwd: str | Path | None = None,
) -> str:
    if reference and reference.strip():
        return reference.strip()

    root = Path.cwd() if cwd is None else Path(cwd)
    if (root / _REPO_ENVIRONMENT_FILE).is_file():
        return _REPO_ENVIRONMENT_REFERENCE
    raise ValueError(
        "No environment reference provided. Expected the canonical generated-repo "
        "environment at freesolo/environment.py with load_environment(), or pass "
        "an explicit reference such as 'freesolo/environment.py:load_environment'."
    )


def _resolve_factory(reference: str) -> Callable[..., object]:
    module_reference, _, attribute_name = reference.partition(":")
    if not attribute_name:
        attribute_name = _DEFAULT_ENVIRONMENT_FACTORY

    module = _import_reference_module(module_reference)
    if not hasattr(module, attribute_name):
        raise AttributeError(
            f"Environment reference {reference!r} does not define {attribute_name!r}"
        )
    factory = getattr(module, attribute_name)
    if not callable(factory):
        raise TypeError(
            f"Environment reference {reference!r} resolved {attribute_name!r}, but it is not callable"
        )
    return factory


def _import_reference_module(module_reference: str) -> ModuleType:
    candidate_path = Path(module_reference)
    if candidate_path.suffix == ".py" or candidate_path.is_file():
        module_path = candidate_path.resolve()
        if not module_path.is_file():
            raise FileNotFoundError(f"Environment file not found: {module_reference}")
        module_name = f"_freesolo_env_{module_path.stem}_{abs(hash(module_path))}"
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise ImportError(f"Could not import environment module from {module_path}")
        module = importlib.util.module_from_spec(spec)
        _prepend_module_dir(module_path.parent)
        previous_module = sys.modules.get(module_name)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception:
            if previous_module is None:
                sys.modules.pop(module_name, None)
            else:
                sys.modules[module_name] = previous_module
            raise
        return module
    return importlib.import_module(module_reference)


def _prepend_module_dir(module_dir: Path) -> None:
    # Generated repo modules live beside config.py and import it as `config`.
    module_dir_text = str(module_dir)
    if module_dir_text not in sys.path:
        sys.path.insert(0, module_dir_text)


def _call_factory(factory: Callable[..., object], kwargs: dict[str, object]) -> object:
    signature = inspect.signature(factory)
    accepts_var_kwargs = any(
        parameter.kind == inspect.Parameter.VAR_KEYWORD
        for parameter in signature.parameters.values()
    )
    if accepts_var_kwargs:
        return factory(**kwargs)
    filtered_kwargs = {
        name: value for name, value in kwargs.items() if name in signature.parameters
    }
    return factory(**filtered_kwargs)


__all__ = [
    "Environment",
    "EnvironmentMultiTurn",
    "EnvironmentSingleTurn",
    "load_environment",
]
